def stop_pty_daemon(work_path: pathlib.Path) -> int:
    """停止后台 C 固件 PTY 守护进程并清理 PID 与控制套接字文件。"""
    pid_file = work_path / "pty_pid"
    if pid_file.exists():
        try:
            os.kill(int(pid_file.read_text(encoding="utf-8").strip()), signal.SIGTERM)
        except OSError:
            pass
        pid_file.unlink()
    sock_path = work_path / "pty_ctl.sock"
    if sock_path.exists():
        sock_path.unlink()
    return 0


def live_pty_ctl(action: str, work_dir: str, ap_url: str = "") -> int:
    """控制 921600 POSIX PTY C 固件桥接守护进程的启动、在线驱动、故障注入、恢复与停止。"""
    work_path = pathlib.Path(work_dir)
    clean_url = ap_url.rstrip("/")
    if action == "start-pty":
        return start_pty_daemon(work_path)
    if action in ("drive-online", "drive-recovery"):
        return 0 if drive_gateway_online_actions(work_path, clean_url) else 1
    if action == "inject-mismatch":
        saved_mc = (work_path / "mc_live.log").read_bytes() if (work_path / "mc_live.log").exists() else b""
        st, _ = http_request_json(f"{clean_url}/api/v1/motion/jog", "POST", b'{"axis":"X","step_mm":5.0}')
        send_pty_ctl_cmd(work_path, "sync_online")
        if saved_mc:
            (work_path / "mc_live.log").write_bytes(saved_mc)
            (work_path / "mc_debug.log").write_bytes(saved_mc)
        return 0 if st == 200 else 1
    if action == "restore-mismatch":
        st, _ = http_request_json(f"{clean_url}/api/v1/motion/jog", "POST", b'{"axis":"X","step_mm":-5.0}')
        send_pty_ctl_cmd(work_path, "sync_online")
        return 0 if st == 200 else 1
    if action == "inject-crc-err":
        return 0 if send_pty_ctl_cmd(work_path, "inject_crc_err") else 1
    if action == "inject-drop":
        return 0 if send_pty_ctl_cmd(work_path, "inject_drop") else 1
    if action == "drive-offline":
        return drive_gateway_offline(work_path, clean_url)
    if action == "stop-pty":
        return stop_pty_daemon(work_path)
    return 2


